def choose_move(observation):
    def g(obj, key, default=None):
        try:
            return obj.get(key, default)
        except Exception:
            return default

    def as_pos(v):
        if v is None:
            return None
        if isinstance(v, (list, tuple)) and len(v) >= 2:
            return [v[0], v[1]]
        if isinstance(v, dict):
            if "pos" in v:
                return as_pos(v.get("pos"))
            x = v.get("x", v.get("col", v.get("c")))
            y = v.get("y", v.get("row", v.get("r")))
            if x is not None and y is not None:
                return [x, y]
        return None

    def extract_positions(v):
        out = []
        if v is None:
            return out
        if isinstance(v, dict):
            if "positions" in v:
                return extract_positions(v.get("positions"))
            if "items" in v:
                return extract_positions(v.get("items"))
            if "agents" in v:
                return extract_positions(v.get("agents"))
            p = as_pos(v)
            if p is not None:
                out.append(p)
            return out
        if isinstance(v, (list, tuple)):
            for e in v:
                if isinstance(e, (list, tuple, dict)):
                    p = as_pos(e)
                    if p is not None:
                        out.append(p)
        return out

    me = as_pos(g(observation, "self"))
    if me is None:
        me = as_pos(g(observation, "agent"))
    if me is None:
        me = as_pos(g(observation, "position"))
    if me is None:
        me = [0, 0]

    mode = g(observation, "mode", g(observation, "task", ""))

    targets = []
    for k in ("resources", "resource", "food", "items", "goals", "goal", "objectives", "territory_targets"):
        targets.extend(extract_positions(g(observation, k)))

    enemies = []
    for k in ("enemies", "opponents", "enemy_agents", "other_agents", "agents"):
        vals = g(observation, k)
        if isinstance(vals, (list, tuple)):
            for e in vals:
                if isinstance(e, dict) and e is g(observation, "self"):
                    continue
                p = as_pos(e)
                if p is not None and p != me:
                    enemies.append(p)

    walls = set()
    for k in ("walls", "blocked", "obstacles"):
        vals = g(observation, k)
        if isinstance(vals, (list, tuple)):
            for e in vals:
                p = as_pos(e)
                if p is not None:
                    walls.add((p[0], p[1]))

    w = g(observation, "width", g(observation, "w"))
    h = g(observation, "height", g(observation, "h"))
    board = g(observation, "board", None)
    grid = g(observation, "grid", None)
    if isinstance(board, (list, tuple)) and not targets:
        for y, row in enumerate(board):
            if isinstance(row, (list, tuple)):
                for x, cell in enumerate(row):
                    if cell in (1, True, "#", "X", "W", "wall"):
                        walls.add((x, y))
                    elif cell in (2, "R", "resource", "food"):
                        targets.append([x, y])
    if isinstance(grid, (list, tuple)) and not targets:
        for y, row in enumerate(grid):
            if isinstance(row, (list, tuple)):
                for x, cell in enumerate(row):
                    if cell in (1, True, "#", "X", "W", "wall"):
                        walls.add((x, y))
                    elif cell in (2, "R", "resource", "food"):
                        targets.append([x, y])

    if not targets:
        cx = (w - 1) / 2 if isinstance(w, int) and w > 0 else 0
        cy = (h - 1) / 2 if isinstance(h, int) and h > 0 else 0
        targets = [[cx, cy]]

    best = [0, 0]
    best_score = None

    for dx in (-1, 0, 1):
        for dy in (-1, 0, 1):
            nx = me[0] + dx
            ny = me[1] + dy
            score = 0.0

            if isinstance(w, int) and (nx < 0 or nx >= w):
                score -= 1000.0
            if isinstance(h, int) and (ny < 0 or ny >= h):
                score -= 1000.0
            if (nx, ny) in walls:
                score -= 1000.0

            # Prefer movement over idling unless already good.
            if dx == 0 and dy == 0:
                score -= 0.25

            # Resource/goal seeking.
            if targets:
                dmin = None
                for t in targets:
                    d = abs(nx - t[0]) + abs(ny - t[1])
                    if dmin is None or d < dmin:
                        dmin = d
                score -= 1.5 * dmin if dmin is not None else 0

            # Threat avoidance in pursuit/evasion and generally.
            nearest_enemy = None
            for e in enemies:
                d = abs(nx - e[0]) + abs(ny - e[1])
                if nearest_enemy is None or d < nearest_enemy:
                    nearest_enemy = d
            if nearest_enemy is not None:
                if "pursuit" in str(mode) or "evasion" in str(mode):
                    score += 0.8 * nearest_enemy
                else:
                    score += 0.15 * nearest_enemy
                if nearest_enemy == 0:
                    score -= 5.0

            # Territory control: drift toward center if no clear target.
            if "territory" in str(mode):
                if isinstance(w, int) and isinstance(h, int) and w > 0 and h > 0:
                    cx = (w - 1) / 2
                    cy = (h - 1) / 2
                    score -= 0.2 * (abs(nx - cx) + abs(ny - cy))

            # Small bias to keep moving when safe.
            score += 0.02 * (abs(dx) + abs(dy))

            if best_score is None or score > best_score:
                best_score = score
                best = [dx, dy]

    return best

